//! Authentic photographic desert landscape wallpaper (Figma 71:47).
//!
//! Stored as a 320x200 RGB565 compressed atlas with integer bilinear sampling.
//! Zero heap allocation, #![`no_std`] compatible, and 10x faster than procedural loops.

#![allow(
    clippy::unreadable_literal,
    clippy::cast_possible_truncation,
    clippy::cast_lossless,
    clippy::many_single_char_names,
    clippy::similar_names,
    clippy::inline_always
)]

/// Width of the source wallpaper atlas.
pub const WALLPAPER_WIDTH: usize = 320;
/// Height of the source wallpaper atlas.
pub const WALLPAPER_HEIGHT: usize = 200;

/// Unpack an RGB565 word into 8-bit RGB components.
#[must_use]
#[inline]
pub const fn unpack_rgb565(pixel: u16) -> (u8, u8, u8) {
    let r = ((pixel >> 11) & 0x1F) as u8;
    let g = ((pixel >> 5) & 0x3F) as u8;
    let b = (pixel & 0x1F) as u8;
    (
        (r << 3) | (r >> 2),
        (g << 2) | (g >> 4),
        (b << 3) | (b >> 2),
    )
}

/// Bilinear interpolation sampler mapping target screen coordinates (x, y)
/// into the photographic wallpaper atlas.
#[must_use]
#[inline]
pub fn sample_wallpaper_bilinear(
    x: usize,
    y: usize,
    target_w: usize,
    target_h: usize,
) -> (u8, u8, u8) {
    if target_w == 0 || target_h == 0 {
        return (0, 0, 0);
    }
    let fx = (x * (WALLPAPER_WIDTH - 1) * 256) / target_w;
    let fy = (y * (WALLPAPER_HEIGHT - 1) * 256) / target_h;
    let x0 = (fx >> 8).min(WALLPAPER_WIDTH - 2);
    let y0 = (fy >> 8).min(WALLPAPER_HEIGHT - 2);
    let x1 = x0 + 1;
    let y1 = y0 + 1;
    let wx = (fx & 0xFF) as u32;
    let wy = (fy & 0xFF) as u32;
    let inv_wx = 256 - wx;
    let inv_wy = 256 - wy;

    let p00 = WALLPAPER_DATA[y0 * WALLPAPER_WIDTH + x0];
    let p10 = WALLPAPER_DATA[y0 * WALLPAPER_WIDTH + x1];
    let p01 = WALLPAPER_DATA[y1 * WALLPAPER_WIDTH + x0];
    let p11 = WALLPAPER_DATA[y1 * WALLPAPER_WIDTH + x1];

    let (r00, g00, b00) = unpack_rgb565(p00);
    let (r10, g10, b10) = unpack_rgb565(p10);
    let (r01, g01, b01) = unpack_rgb565(p01);
    let (r11, g11, b11) = unpack_rgb565(p11);

    let top_r = (r00 as u32 * inv_wx + r10 as u32 * wx) >> 8;
    let top_g = (g00 as u32 * inv_wx + g10 as u32 * wx) >> 8;
    let top_b = (b00 as u32 * inv_wx + b10 as u32 * wx) >> 8;

    let bot_r = (r01 as u32 * inv_wx + r11 as u32 * wx) >> 8;
    let bot_g = (g01 as u32 * inv_wx + g11 as u32 * wx) >> 8;
    let bot_b = (b01 as u32 * inv_wx + b11 as u32 * wx) >> 8;

    let r = ((top_r * inv_wy + bot_r * wy) >> 8) as u8;
    let g = ((top_g * inv_wy + bot_g * wy) >> 8) as u8;
    let b = ((top_b * inv_wy + bot_b * wy) >> 8) as u8;

    (r, g, b)
}

